    should_trigger = marker_map.get(tier_letter) in markers

    # Generate value that may or may not trigger based on markers
    if should_trigger:
        # Trigger the threshold (value crosses it)
        if threshold < 0:  # Negative threshold, trigger if value <= threshold
            return threshold - random.uniform(0.5, 3)
        else:  # Positive threshold, trigger if value >= threshold
            return threshold + random.uniform(0.5, 3)
    else:
        # Don't trigger
        if threshold < 0:
            return threshold + random.uniform(1, 5)
        else:
            return threshold - random.uniform(1, 5)

# Generate all indicator values
indicators = {}
