    if info['triggered']:
        tier_counts[info['tier']] += 1

# Composite rule
if tier_counts['A'] >= 2 and tier_counts['B'] >= 1 and tier_counts['C'] >= 1:
    composite = 'RED'
elif tier_counts['A'] >= 2 and tier_counts['B'] >= 1:
    composite = 'ORANGE'
elif tier_counts['A'] >= 2:
    composite = 'YELLOW'
else:
    composite = 'GREEN'

# Generate report
report = f"""AI DISPLACEMENT RISK MONITOR
As of: {input_data['as_of']}

=== SIGNAL BOARD ===
"""

for code in sorted(indicators.keys()):
    info = indicators[code]
    status = '⚠ TRIGGERED' if info['triggered'] else '✓ OK'
    direction = '↑' if info['value'] >= info['threshold'] else '↓'
    report += f"{code} [{info['tier']}]: {info['name']}: {info['value']} (thr: {info['threshold']}) {direction} {status}\n"

report += f"\n=== COMPOSITE RISK LIGHT ===\n{composite}\n"

report += f"\n=== ACTIONABLE NOTES ===\n"
if composite == 'RED':
    report += "- HIGH RISK: Full escalation. Reduce exposure to white-collar intensive sectors.\n"
    report += "- Prepare for labor market stress and credit deterioration.\n"
elif composite == 'ORANGE':
    report += "- ELEVATED RISK: Monitor Tier C spillovers closely.\n"
    report += "- Consider hedging labor-dependent positions.\n"
elif composite == 'YELLOW':
    report += "- MODERATE RISK: Tier A signals active but no labor market confirmation yet.\n"
    report += "- Watch for Tier B confirmation in coming weeks.\n"
else:
    report += "- LOW RISK: No immediate displacement signals. Maintain baseline monitoring.\n"

report += f"\n=== DATA GAPS ===\n"
report += "- All 10 indicators present.\n"
report += f"- Seed: {input_data.get('note', 'N/A')}\n"

print(report)

# Save to output.txt
with open('output.txt', 'w') as f:
    f.write(report)

print("\n[Report saved to output.txt]")
EOF\n",
